import {samples,buildIndex,search,excerpt,evaluate} from './engine.js';
let docs=structuredClone(samples),index,lastTrace=null;
const $=s=>document.querySelector(s);
const el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
const countWords=t=>(t.match(/\S+/g)||[]).length;
function clearResults(){lastTrace=null;$('#results').replaceChildren();$('#evaluation').replaceChildren();$('#status').textContent='';}
function reindex(){index=buildIndex(docs,Number($('#chunk-size').value));$('#doc-count').textContent=String(docs.length).padStart(2,'0');$('#index-stats').textContent=`${docs.length} documents · ${index.chunks.length} chunks · local index ready`;$('#documents').replaceChildren();for(const doc of docs){const row=el('div','document');row.append(el('span','', '▤'));const info=el('div');info.append(el('strong','',doc.name),el('small','',`${countWords(doc.text)} words · ${samples.some(s=>s.id===doc.id)?'sample':'uploaded'}`));const remove=el('button','remove','×');remove.type='button';remove.setAttribute('aria-label',`Remove ${doc.name}`);remove.onclick=()=>{docs=docs.filter(d=>d.id!==doc.id);clearResults();reindex();};row.append(info,remove);$('#documents').append(row);}}
function downloadTrace(){if(!lastTrace)return;const blob=new Blob([JSON.stringify(lastTrace,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download='evidence-lab-trace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function ask(question){clearResults();if(!docs.length){$('#status').textContent='Add a document or restore the sample corpus to search.';return;}const start=performance.now();const hits=search(index,question,Number($('#top-k').value));const elapsed=performance.now()-start;const results=$('#results');if(!hits.length){results.append(el('p','empty-answer','No matching evidence found. Try wording that appears in your documents, or add a relevant source. No answer has been generated.'));return;}const head=el('div','result-header');head.append(el('h4','','Retrieved evidence'),el('small','',`${hits.length} passages · ${elapsed.toFixed(1)} ms`));results.append(head);const excerpts=hits.map(h=>excerpt(h,question));hits.forEach((hit,i)=>{const p=el('p','excerpt',excerpts[i]);const ref=el('button','citation',`[${i+1}]`);ref.type='button';ref.setAttribute('aria-label',`Open source ${i+1}: ${hit.name}`);ref.onclick=()=>{const source=document.getElementById(`source-${i}`);source.open=true;source.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'nearest'});source.querySelector('summary').focus();};p.append(ref);results.append(p);});results.append(el('p','sources-title','SOURCES / INSPECT THE CONTEXT'));hits.forEach((hit,i)=>{const details=el('details','source');details.id=`source-${i}`;details.append(el('summary','',`[${i+1}] ${hit.name} · chunk ${hit.number}`),el('div','source-meta',`BM25 score ${hit.score.toFixed(3)} · relevance signal, not confidence`),el('p','',hit.text));results.append(details);});lastTrace={version:1,mode:'BM25 retrieval with verbatim extractive assembly; no LLM',question,settings:{chunkWords:Number($('#chunk-size').value),overlap:.2,topK:Number($('#top-k').value)},elapsedMs:elapsed,results:hits.map((h,i)=>({source:h.name,chunk:h.number,score:h.score,text:h.text,excerpt:excerpts[i]}))};const exportButton=el('button','quiet','Download query trace ↓');exportButton.onclick=downloadTrace;results.append(exportButton);}
$('#query-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#question').value.trim();if(q)ask(q);});
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{$('#question').value=b.dataset.question;ask(b.dataset.question);});
$('#files').addEventListener('change',async e=>{clearResults();const errors=[];let total=docs.reduce((n,d)=>n+new TextEncoder().encode(d.text).length,0);for(const file of [...e.target.files]){if(!/\.(txt|md)$/i.test(file.name)){errors.push(`${file.name}: use .txt or .md.`);continue;}if(file.size>2*1024*1024){errors.push(`${file.name}: exceeds 2 MB.`);continue;}if(docs.length>=20||total+file.size>8*1024*1024){errors.push(`${file.name}: session limit reached (20 documents / 8 MB).`);continue;}try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());if(!text.trim()){errors.push(`${file.name}: empty file.`);continue;}if(text.includes('\0')){errors.push(`${file.name}: binary content is unsupported.`);continue;}docs.push({id:crypto.randomUUID(),name:file.name,text});total+=file.size;}catch{errors.push(`${file.name}: could not read UTF-8 text.`);}}e.target.value='';reindex();$('#status').textContent=errors.length?errors.join(' '):'Documents added. Ask a question about their contents.';});
for(const id of ['chunk-size','top-k'])$('#'+id).onchange=()=>{clearResults();reindex();$('#status').textContent='Settings updated. Submit your question to retrieve again.';};
$('#reset').onclick=()=>{docs=structuredClone(samples);clearResults();reindex();$('#status').textContent='Sample corpus restored.';};
$('#evaluate').onclick=()=>{const panel=$('#evaluation');panel.replaceChildren();const checks=evaluate();const head=el('div','result-header');head.append(el('h4','',`Sample evaluation · ${checks.filter(c=>c.pass).length}/${checks.length} passed`));panel.append(head);checks.forEach(c=>{const row=el('div','eval-row');row.append(el('span','',c.name),el('strong',c.pass?'pass':'fail',c.pass?'PASS':'FAIL'));panel.append(row);});panel.append(el('p','eval-note','Five deterministic smoke checks against a fresh sample index. These test retrieval wiring, no-match behavior, and excerpt fidelity; they do not measure arbitrary-document answer quality.'));};
reindex();
